html:
{% set data = get_order_sheet_stage_workflow(doc.name) %}
{% set items = data.rows %}
<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #111; padding: 10px; }
  .print-format { margin-top: 0mm; margin-right: 0mm; margin-bottom: 0mm; margin-left: 0mm; orientation: Landscape; }

  .jos-header { text-align: center; margin-bottom: 10px; }
  .jos-header img { width: 100%; max-height: 55px; object-fit: contain; display: block; margin: 0 auto 8px; }
  .jos-header h2 { margin: 0; font-size: 20px; letter-spacing: 1px; }

  .jos-ref { text-align: center; margin-bottom: 12px; }
  .jos-date-box { display: inline-block; border: 1.5px solid #d97757; padding: 4px 14px; font-weight: bold; font-size: 12px; color: #111; margin-right: 10px; }
  .jos-items-count { font-size: 12px; color: #555; }

  table.jos-items { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
  table.jos-items th { background: #fff; color: #111; font-weight: bold; border-bottom: 2px solid #d97757; padding: 6px 8px; text-align: left; font-size: 12px; white-space: nowrap; }
  table.jos-items td { border-bottom: 1px solid #ddd; padding: 6px 8px; vertical-align: middle; font-size: 12px; }
  table.jos-items tr:nth-child(even) td { background: #fafafa; }
  table.jos-items td.jos-item-code { font-weight: bold; }
  table.jos-items th.jos-stage-col,
  table.jos-items td.jos-stage-cell { text-align: center; white-space: nowrap; }

  .jos-subnote { font-size: 10px; margin-top: 2px; }
  .jos-confirmed { font-weight: bold; color: #111; }

  .jos-stage-na { color: #aaa; }
  .jos-stage-pending { color: #999; }
  .jos-stage-done { color: #111; }
  .jos-stage-current { font-weight: bold; background: #fdf1ec; }
  .jos-stage-hold { font-weight: bold; color: #b3261e; }

  .jos-empty { text-align: center; padding: 20px; color: #888; font-size: 12px; }

  .jos-footer { margin-top: 20px; width: 100%; }
  .jos-footer td { padding: 4px; }
  .sig-line { border-top: 1px solid #444; padding-top: 4px; text-align: center; font-size: 10px; color: #555; }
</style>

<div class="jos-header">
  <img src="/files/Instabiz_LH_v2.png">
  <h2>JOB ORDER SUMMARY</h2>
</div>

<div class="jos-ref">
  <span class="jos-date-box">Sheet Date: {{ frappe.utils.formatdate(doc.creation, "dd-MMM-yy") if doc.creation else "" }}</span>
  <span class="jos-items-count">Items: {{ items | length }}</span>
</div>

{% if items %}
<table class="jos-items">
  <thead>
    <tr>
      <th>#</th>
      <th>Item Code</th>
      <th>Item Name</th>
      <th>Qty</th>
      {% if data.any_color %}<th>Color</th>{% endif %}
      {% if data.any_width_mm %}<th>Width (MM)</th>{% endif %}
      {% if data.any_length_mtr %}<th>Length (MTR)</th>{% endif %}
      {% if data.any_qty_pkg %}<th>Qty/Pkg</th>{% endif %}
      {% if data.any_total_pkg %}<th>Total Pkg</th>{% endif %}
      <th class="jos-stage-col">Coating</th>
      <th class="jos-stage-col">Slitting</th>
      <th class="jos-stage-col">Rewinding</th>
      <th class="jos-stage-col">Cutting</th>
      <th class="jos-stage-col">Packing</th>
      <th class="jos-stage-col">RTD</th>
    </tr>
  </thead>
  <tbody>
  {% for item in items %}
    <tr>
      <td>{{ loop.index }}</td>
      <td class="jos-item-code">{{ item.item_code }}</td>
      <td>{{ item.item_name or "" }}</td>
      <td>
        <div>{{ item.qty or 0 }} {{ item.uom or "" }}</div>
        {%- if item.uom == "PCS" and item.pcs_to_make -%}
        <div class="jos-subnote jos-confirmed">{{ item.pcs_to_make }} pcs confirmed</div>
        {%- elif item.uom == "SQMT" and item.logs_to_make -%}
        <div class="jos-subnote jos-confirmed">{{ item.logs_to_make }} logs confirmed</div>
        {%- endif -%}
      </td>
      {% if data.any_color %}<td>{{ item.color or "-" }}</td>{% endif %}
      {% if data.any_width_mm %}<td>{{ item.width_mm if item.width_mm else "-" }}</td>{% endif %}
      {% if data.any_length_mtr %}<td>{{ item.length_mtr if item.length_mtr else "-" }}</td>{% endif %}
      {% if data.any_qty_pkg %}<td>{{ (item.qty_pkg | int) if item.qty_pkg else "-" }}</td>{% endif %}
      {% if data.any_total_pkg %}<td>{{ (item.total_pkg | int) if item.total_pkg else "-" }}</td>{% endif %}
      {% for st in item.stages %}
        {%- if not st.in_route -%}
        <td class="jos-stage-cell jos-stage-na">&mdash;</td>
        {%- elif st.status == "Completed" -%}
        <td class="jos-stage-cell jos-stage-done">{{ st.machine or "Done" }}</td>
        {%- elif st.status == "On Hold" -%}
        <td class="jos-stage-cell jos-stage-hold">{{ st.machine or "" }} (Hold)</td>
        {%- elif st.is_current -%}
        <td class="jos-stage-cell jos-stage-current">{{ st.machine or "Pending" }}</td>
        {%- else -%}
        <td class="jos-stage-cell jos-stage-pending">pending</td>
        {%- endif -%}
      {% endfor %}
    </tr>
  {% endfor %}
  </tbody>
</table>
{% else %}
<div class="jos-empty">No items to print for this order.</div>
{% endif %}

<table class="jos-footer">
  <tr>
    <td style="width:33%"><div class="sig-line">Operator Signature</div></td>
    <td style="width:33%"><div class="sig-line">Actual Output Qty / Date</div></td>
    <td style="width:33%"><div class="sig-line">Checked By</div></td>
  </tr>
</table>
